"""Public legal documents and their immutable consent version.

Only public operator details belong in privacy_* site settings. Nothing here
asserts that hosting/localisation or the operator's procedures were audited.
"""
import hashlib
import json

REQUIRED = ("operator", "address", "hosting", "recipients", "retention", "security")


def consent_error(document: dict, consent: bool, version: str) -> tuple[int, str] | None:
    if not document["ready"]:
        return 503, "Приём заявок временно приостановлен: документы об обработке данных ещё не утверждены."
    if consent is not True or version != document["version"]:
        return 422, "Подтвердите отдельное согласие на обработку данных. Если документ обновился, перезагрузите страницу."
    return None


def privacy_document(settings: dict[str, str]) -> dict:
    values = {key: settings.get(f"privacy_{key}", "").strip() for key in REQUIRED}
    ready = settings.get("privacy_approved") == "true" and all(values.values())
    value = lambda key: values[key] or "Не заполнено оператором"
    email = settings.get("contact_email", "message@awwwdde.art").strip() or "message@awwwdde.art"
    policy = [
        {"title": "1. Оператор и область действия", "body": f"Оператор сайта https://awwwdde.art: {value('operator')}. Адрес для обращений: {value('address')}. Email по вопросам персональных данных: {email}. Политика относится к форме обратной связи на сайте."},
        {"title": "2. Цель и состав данных", "body": "Цель — рассмотреть обращение о разработке или дизайне сайта и ответить заявителю. Форма передаёт имя, email и текст сообщения. Сервер также сохраняет IP-адрес, User-Agent, источник и время обращения. Не указывайте в сообщении паспортные данные, сведения о здоровье и другие специальные категории данных. Данные формы не предназначены для рекламных рассылок или публикации."},
        {"title": "3. Основание и способы обработки", "body": "Основание обработки заявки — отдельное добровольное согласие заявителя (п. 1 ч. 1 ст. 6, ст. 9 Федерального закона № 152-ФЗ). Обработка автоматизированная и без средств автоматизации: сбор, запись, систематизация, накопление, хранение, уточнение, извлечение, использование для ответа, блокирование, удаление и уничтожение. Факт согласия, время и версия документов сохраняются вместе с заявкой. Для обработки по договору применяются самостоятельные законные основания."},
        {"title": "4. Хранение и получатели", "body": f"Размещение сайта и базы заявок: {value('hosting')}. Лица, имеющие доступ, и обработчики: {value('recipients')}. Срок и порядок хранения, включая резервные копии и технические журналы: {value('retention')}. Использование иностранных сервисов и трансграничная передача должны быть отдельно оценены оператором до их подключения."},
        {"title": "5. Защита данных", "body": f"Доступ к сохранённым заявкам в приложении требует авторизации. Меры защиты и порядок реагирования оператора: {value('security')}."},
        {"title": "6. Запросы и отзыв согласия", "id": "requests", "body": f"Вы можете запросить сведения об обработке своих данных, потребовать уточнения, блокирования или уничтожения в предусмотренных законом случаях, а также отозвать согласие. Напишите на {email} с темой «Персональные данные» и укажите email, использованный при обращении. Не присылайте копию паспорта без необходимости. Ответ на запрос о данных предоставляется в течение 10 рабочих дней; продление не более чем на 5 рабочих дней требует мотивированного уведомления. При отзыве согласия данные уничтожаются в срок до 30 дней, если нет другого законного основания для обработки. Можно обратиться в Роскомнадзор или суд."},
        {"title": "7. Хранение в браузере и внешние ссылки", "body": "Сайт сохраняет выбранный язык в localStorage. Для служебного предпросмотра и административного входа используются отдельные записи localStorage. В текущем коде публичной части нет рекламных и аналитических счётчиков. Это описание не охватывает неизвестные настройки хостинга и прокси. При переходе в социальные сети действуют правила соответствующих сервисов; для обращения через форму переходить туда не требуется."},
    ]
    consent = [
        {"title": "Отдельное согласие на обработку персональных данных", "body": f"Я свободно, своей волей и в своём интересе даю оператору {value('operator')}, адрес: {value('address')}, согласие на обработку имени, email, текста моего обращения, IP-адреса, User-Agent, источника и времени отправки в целях рассмотрения обращения о разработке или дизайне сайта и ответа на него. Согласие не включает рекламные рассылки и распространение данных."},
        {"title": "Операции и условия", "body": f"Разрешаю автоматизированную и неавтоматизированную обработку: сбор, запись, систематизацию, накопление, хранение, уточнение, извлечение, использование для ответа, блокирование, удаление и уничтожение. Получатели и обработчики: {value('recipients')}. Размещение: {value('hosting')}. Срок действия согласия и хранения: {value('retention')}. Согласие можно отозвать письмом на {email}. При отсутствии иных оснований обработка прекращается и данные уничтожаются в предусмотренные законом сроки."},
        {"title": "Как выражается согласие", "body": "Согласие выражается самостоятельной отметкой в изначально пустом поле «Даю согласие на обработку персональных данных» и отправкой формы. Оно оформлено отдельно от политики и иных документов. Сохраняются дата, версия и текст согласия; без отметки заявка не отправляется."},
    ]
    snapshot = json.dumps({"policy": policy, "consent": consent}, ensure_ascii=False, sort_keys=True)
    version = hashlib.sha256(snapshot.encode()).hexdigest()
    return {"ready": bool(ready), "version": version, "policy": policy, "consent": consent, "contact_email": email}
